observation.command:
cd /workspace && echo "=== create sva_job_worker role + run graphile worker schema migration ==="
export POSTGRES_DB=sva_studio POSTGRES_USER=sva POSTGRES_PASSWORD=sva_local_dev_password POSTGRES_HOST=127.0.0.1 POSTGRES_PORT=5432
# create worker role
docker exec -i sva-studio-postgres psql -v ON_ERROR_STOP=1 -U sva -d sva_studio <<'SQL'
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='sva_job_worker') THEN
    CREATE ROLE sva_job_worker LOGIN PASSWORD 'sva_job_worker_local_dev_password' NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT;
  ELSE
    ALTER ROLE sva_job_worker WITH LOGIN PASSWORD 'sva_job_worker_local_dev_password';
  END IF;
END $$;
GRANT CONNECT ON DATABASE sva_studio TO sva_job_worker;
SQL
echo "role created, running graphile worker migration:"
timeout 200 node deploy/portainer/migrate-graphile-worker.mjs 2>&1 | tail -15; echo "EXIT: ${PIPESTATUS[0]}"
